import { useUI } from "../runtime/store.js";
import { runActions } from "../runtime/actions.js";
import Button from "../components/Button.jsx";
import Checkbox from "../components/Checkbox.jsx";
import Container from "../components/Container.jsx";
import Divider from "../components/Divider.jsx";
import Header from "../components/Header.jsx";
import Heading from "../components/Heading.jsx";
import Icon from "../components/Icon.jsx";
import Message from "../components/Message.jsx";
import Page from "../components/Page.jsx";
import Radio from "../components/Radio.jsx";
import Text from "../components/Text.jsx";

const BTN_SAVE_CLICK = [
  {
    "type": "show_message",
    "text": "Privacy settings saved",
    "tone": "success"
  }
];

export default function MainPage() {
  const ui = useUI();
  const handleBtnSaveClick = () => runActions("btn_save", BTN_SAVE_CLICK, ui);

  return (
    <Page id="page_main" layout={{ gap: 22 }} style={{ maxWidth: 596 }}>
      <Header
        id="hdr_privacy_header"
        layout={{ direction: "row", align: "center", justify: "between" }}
      >
        <Icon id="ico_back_icon" label="Back icon" />
        <Heading id="h_privacy" label="Privacy" level={1} />
        <Text id="txt_y" label="y" />
      </Header>
      <Text id="txt_profile_visibility" label="Profile visibility" />
      <Radio id="rad_public" label="Public" />
      <Radio
        id="rad_profile_visibility_options"
        label="Profile visibility options"
        group="profile_visibility"
      />
      <Radio id="rad_private" label="Private" />
      <Divider id="div_divider" style={{ width: "100%" }} />
      <Checkbox id="chk_show_online_status" label="Show online status" />
      <Checkbox id="chk_allow_tagging" label="Allow tagging" />
      <Container id="box_12" layout={{ direction: "row", align: "center" }}>
        <Button id="btn_save" label="Save" onClick={handleBtnSaveClick} />
        <Message owner="btn_save" />
        <Button id="btn_reset" label="Reset" style={{ alignSelf: "flex-end" }} />
      </Container>
    </Page>
  );
}

