        label="Profile visibility options"
        group="profile_visibility"
      />
      <Radio id="rad_private" label="Private" />
      <Divider id="div_divider" style={{ width: "100%" }} />
      <Checkbox id="chk_show_online_status" label="Show online status" />
      <Checkbox id="chk_allow_tagging" label="Allow tagging" />
      <Container id="box_12" layout={{ direction: "row", align: "center" }}>
