        <Message owner="btn_save" />
        <Button id="btn_reset" label="Reset" style={{ alignSelf: "flex-end" }} />
      </Container>
    </Page>
  );
}

const PAGES = {
  page_main: MainPage,
};

const INITIALLY_HIDDEN = {};

function App() {
  const ui = useUIStore("page_main", INITIALLY_HIDDEN);
  const CurrentPage = PAGES[ui.page] ?? MainPage;

  return (
    <UIContext.Provider value={ui}>
      <div className="ng-app">
        <CurrentPage />
      </div>
    </UIContext.Provider>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<App />);

